package com.ecommerce.cart.controller;
import com.ecommerce.cart.dto.ItemRequest;import com.ecommerce.cart.model.Cart;import com.ecommerce.cart.service.CartService;import jakarta.validation.Valid;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.Map;
@RestController @RequestMapping("/api/cart") public class CartController {private final CartService s;public CartController(CartService s){this.s=s;}private String uid(Authentication a){return (String)a.getPrincipal();}@GetMapping public Map<String,Object> get(Authentication a){return s.view(uid(a));}@PostMapping("/items")public Cart add(Authentication a,@Valid @RequestBody ItemRequest r){return s.add(uid(a),r);}@PatchMapping("/items/{pid}")public Cart update(Authentication a,@PathVariable String pid,@Valid @RequestBody ItemRequest r){return s.update(uid(a),pid,r.getQuantity());}@DeleteMapping("/items/{pid}")public Cart remove(Authentication a,@PathVariable String pid){return s.remove(uid(a),pid);}@DeleteMapping public Map<String,String> clear(Authentication a){s.clear(uid(a));return Map.of("message","Cart cleared");}}